import {PrismaClient} from '@prisma/client';
const prisma=new PrismaClient();
const docs=[
  {type:"COOKIE_POLICY",slug:"cerez-politikasi",title:"Çerez Politikası",body:"ÇEREZ POLİTİKASI\n\nÇerez Nedir?\n\nÇerez, bir siteyi ziyaret ettiğinizde sitenin bilgisayarınıza veya mobil cihazınıza kaydettiği küçük boyutlu bir metin dosyasıdır. Çerezler bir web sitesinin çalışması, daha verimli çalışması veya web sitesinin sahiplerine bilgi sağlamak için yaygın olarak kullanılmaktadır. Çerezler hakkında daha detaylı bilgi için https://www.aboutcookies.org ve https://www.allaboutcookies.org adreslerini ziyaret edebilirsiniz.\n\nNe için kullanılır?\n\nÇerezler bilgisayarlarda, telefonlarda ve diğer cihazlarda sizi tanımlayan bilgileri ve siteyi kullanırken yaptığınız hareketleri, kullanım alışkanlıklarınızı toplamak, tutmak ve devamında internet sitemizi iyileştirmek ve size özel kişiselleştirmek için kullanılır. Biz de {store_name} olarak {store_domain} internet sayfasında, site içeriği ile nasıl etkileşime geçtiğinizi tespit etmek ve kullanıcı deneyiminizi geliştirebilmek için çeşitli çerezler kullanmaktayız. Web sitemizde kullanılan çerezler hakkında daha detaylı bilgi edinmek için Çerez Tablomuzu inceleyebilirsiniz.\n\nBirinci Taraf ve Üçüncü Taraf Çerezler\n\n{store_owner}’ye ait {store_domain} internet sayfasında hem birinci taraf hem de üçüncü taraf çerezler kullanılmaktadır. Birinci taraf çerezler, şirketimiz tarafından {store_domain} domainine yerleştirilmiş ve sadece {store_owner} tarafından okunabilen; kullanıcının dil, lokasyon tercihi gibi temel site fonksiyonlarının yerine getirilmesi sürecinde kullanıcı deneyiminizi geliştirebilmek amacıyla kullanılan çerezlerdir. Üçüncü taraf çerezler, {store_owner}’nin iş ortakları veya servis sağlayıcılar gibi üçüncü kişilere ait ve üçüncü kişiler tarafından yürütülen çerezlerdir.\n\nWebsitemizde Kullanılan Çerezler\n\nOtantikasyon Çerezleri: Üyelerimizin her sayfada şifrelerini yeniden girmemeleri için kullanılan çerezlerdir. Facebook connect girişlerinde de benzer çerezler kullanılmaktadır.\n\nReklam Çerezleri: Davranışsal ve hedef odaklı reklamların ziyaretçilere gösterilmesi amacıyla kullanılan çerezlerdir.\n\nAnalitik Çerezler: Üyelerimizin/ziyaretçilerimizin kullanım alışkanlıklarını analiz etmek ve uygulama istatistiklerini belirlemek için kullanılan çerezlerdir.\n\nTeknik Çerezler: İnternet sitesinin düzgün çalışmasının takibi amacıyla kullanılan çerezlerdir.\n\nKişiselleştirme Çerezleri: Kullanıcı davranış ve tercihlerine göre kişiselleştirilmiş içerik ve deneyim sunmak amacıyla kullanılan çerezlerdir.\n\nÇerezleri Nasıl Silebilirim veya Reddedebilirim?\n\n{store_domain} internet sayfasında, sitemizin aktif ve verimli bir şekilde çalışması için birtakım zorunlu çerezler kullanılmaktadır. Zorunlu çerezlerin dışında kalan çerez grupları varsayılan olarak devre dışıdır. Kullanıcılarımız, istekleri doğrultusunda bu çerezleri aktif hale getirebilir veya daha sonra tekrar devre dışı bırakabilir. Zorunlu olmayan çerezlerin devre dışı bırakılması sitenin bazı işlevlerinin sınırlı çalışmasına neden olabilir.\n\nTarayıcınızın yardım veya destek sayfalarından çerez tercihlerinizi yönetebilirsiniz. Ayrıca www.youronlinechoices.eu/tr/ adresini ziyaret edebilirsiniz.",translations:{"en-US": {"title": "Cookie Policy", "slug": "cookie-politikasi", "body": "COOKIE POLICY\n\nWhat is a cookie?\n\nA cookie is a small text file stored on your computer or mobile device when you visit a website. Cookies are commonly used to make websites work, improve efficiency and provide information to website owners.\n\nWhy do we use cookies?\n\n{store_name} uses cookies on {store_domain} to understand how visitors interact with the site, remember preferences, improve functionality, perform analytics and, where consent is required, personalize content and advertising.\n\nFirst-party and third-party cookies\n\n{store_domain}, operated by {store_owner}, may use first-party cookies set by the store and third-party cookies provided by service providers and business partners.\n\nCookie categories\n\nAuthentication cookies help keep members signed in. Advertising cookies support targeted advertising where the visitor has consented. Analytics cookies help measure site usage. Technical cookies are necessary for the site to operate correctly. Personalization cookies remember user preferences.\n\nHow can I reject cookies?\n\nStrictly necessary cookies may be used because they are required for the site to function. Other cookie categories are disabled by default where consent is legally required and can be enabled or disabled through cookie preferences. Disabling optional cookies may limit certain functions."}, "de-DE": {"title": "Cookie-Richtlinie", "slug": "cerez-politikasi-de", "body": "COOKIE-RICHTLINIE\n\nCookies sind kleine Textdateien, die beim Besuch einer Website auf dem Endgerät gespeichert werden. {store_name} verwendet auf {store_domain} notwendige Cookies für den Betrieb der Website sowie – soweit eine Einwilligung erforderlich ist – Analyse-, Personalisierungs- und Marketing-Cookies.\n\nErstanbieter-Cookies werden von {store_domain}/{store_owner} gesetzt. Drittanbieter-Cookies können von Dienstleistern und Geschäftspartnern stammen. Nicht notwendige Cookie-Kategorien können über die Cookie-Einstellungen aktiviert oder deaktiviert werden. Das Deaktivieren optionaler Cookies kann einzelne Funktionen einschränken."}, "ru-RU": {"title": "Политика использования файлов cookie", "slug": "cerez-politikasi-ru", "body": "ПОЛИТИКА COOKIE\n\nCookie — это небольшие текстовые файлы, сохраняемые на устройстве при посещении сайта. {store_name} использует на {store_domain} обязательные cookie для работы сайта, а также, когда требуется согласие, аналитические, персонализационные и рекламные cookie. Cookie первой стороны устанавливаются {store_domain}/{store_owner}; cookie третьих сторон могут предоставляться партнёрами и поставщиками услуг. Необязательные категории можно включать и отключать в настройках cookie."}, "ar-SA": {"title": "سياسة ملفات تعريف الارتباط", "slug": "cerez-politikasi-ar", "body": "سياسة ملفات تعريف الارتباط\n\nملف تعريف الارتباط هو ملف نصي صغير يُحفظ على جهازك عند زيارة موقع إلكتروني. تستخدم {store_name} على {store_domain} ملفات تعريف الارتباط الضرورية لتشغيل الموقع، وكذلك ملفات التحليل والتخصيص والإعلان عندما يتطلب القانون موافقة المستخدم. يتم تعيين ملفات الطرف الأول بواسطة {store_domain}/{store_owner}، وقد تأتي ملفات الطرف الثالث من مزودي الخدمات والشركاء. يمكن إدارة الفئات غير الضرورية من إعدادات ملفات تعريف الارتباط."}}},
  {type:"PRIVACY",slug:"gizlilik-ve-guvenlik",title:"Gizlilik ve Güvenlik",body:"GİZLİLİK\n\n{store_domain}'de sizlere daha iyi hizmet verebilmek amacıyla bazı kişisel bilgilerinizi (isim, yaş, ilgi alanlarınız, e-posta vb.) talep ediyoruz. {store_name} bilgisayarlarında toplanan bu bilgiler, dönemsel kampanya çalışmalarımızda, müşterilerimize yönelik özel promosyon faaliyetlerimizde ve ilgi alanlarınıza yönelik iletişim çalışmalarında {store_name} bünyesinde kullanılmaktadır.\n\n{store_domain}, tarafınızdan kayıt formunda yazılmış olan veya daha sonra güncellenen adres, e-posta adresi, sabit ve mobil telefon hatları ve diğer iletişim bilgileriniz üzerinden, yürürlükteki mevzuata ve tercihlerinize uygun şekilde iletişim kurabilir. Siparişlerinizin doğru, hızlı ve sorunsuz şekilde teslim edilmesini sağlamak amacıyla teslimat çözüm ortağı kargo firmaları ile gerekli adres ve iletişim bilgileri paylaşılabilir.\n\nÜyelik formlarında toplanan bilgileriniz, yasal zorunluluklar ve hizmetin ifası için gerekli haller dışında üçüncü şahıslarla paylaşılmaz, faaliyet dışı ticari amaçlarla kullanılmaz ve satılmaz.\n\n{store_domain}, site kullanımı sırasında ziyaretçi hareketi ve tercihlerini analiz ederek yorumlayabilir. Kişisel bilgiler içermeyen istatistiksel veriler, daha iyi bir alışveriş deneyimi sağlamak amacıyla iş ortaklarıyla paylaşılabilir.\n\nÖdeme sayfasında paylaştığınız kredi kartı bilgileri güvenliği en üst seviyede tutmak amacıyla {store_domain} veya ona hizmet veren şirketlerin sunucularında açık olarak tutulmaz.\n\nGÜVENLİK\n\n\"Güvenli alışveriş\" ve \"kişisel bilgilerin gizliliği\" ilke edinen {store_domain}, SSL/TLS başta olmak üzere güvenli iletişim protokolleri ile çalışır. Kart bilgileriniz ödeme altyapısına şifreli bağlantı üzerinden iletilir ve sistemlerimiz tarafından açık kart numarası olarak depolanmaz.\n\n{store_domain} üzerindeki deneyimlerinizi ve sorularınızı {store_mail} adresinden bizimle paylaşabilirsiniz.\n\nKeyifli alışverişler.",translations:{"en-US": {"title": "Privacy and Security", "slug": "privacy-security", "body": "PRIVACY AND SECURITY\n\n{store_name} may process personal information you provide to {store_domain}, such as identity, contact and order information, in order to provide the service, manage orders, support customers, comply with legal obligations and carry out marketing only where a valid legal basis or consent exists. Information is not sold and is shared with third parties only where required to provide the service, comply with law or where you have authorized it.\n\nShipping providers may receive necessary name, address and contact details to deliver orders. Payment card data is transmitted securely to payment providers and is not stored by {store_domain} as a full readable card number.\n\nSECURITY\n\n{store_domain} uses encrypted HTTPS/TLS connections and appropriate technical and administrative safeguards. Questions may be sent to {store_mail}."}, "de-DE": {"title": "Datenschutz und Sicherheit", "slug": "gizlilik-ve-guvenlik-de", "body": "DATENSCHUTZ UND SICHERHEIT\n\n{store_name} verarbeitet personenbezogene Daten, die über {store_domain} bereitgestellt werden, insbesondere Identitäts-, Kontakt-, Bestell- und technische Nutzungsdaten, zur Vertragserfüllung, Kundenbetreuung, Sicherheit, Erfüllung gesetzlicher Pflichten und – bei bestehender Rechtsgrundlage oder Einwilligung – zu Marketingzwecken. Daten werden nicht verkauft. Erforderliche Daten können insbesondere an Versand-, Zahlungs-, Hosting- und sonstige Dienstleister weitergegeben werden. Vollständige Kreditkartennummern werden nicht offen auf den Systemen von {store_domain} gespeichert.\n\n{store_domain} nutzt HTTPS/TLS und angemessene technische und organisatorische Sicherheitsmaßnahmen. Fragen: {store_mail}."}, "ru-RU": {"title": "Конфиденциальность и безопасность", "slug": "gizlilik-ve-guvenlik-ru", "body": "КОНФИДЕНЦИАЛЬНОСТЬ И БЕЗОПАСНОСТЬ\n\n{store_name} обрабатывает персональные данные, предоставленные через {store_domain}, включая идентификационные, контактные, заказные и технические данные, для исполнения заказов, обслуживания клиентов, безопасности, выполнения юридических обязанностей и, при наличии законного основания или согласия, маркетинга. Данные не продаются. Необходимые сведения могут передаваться службам доставки, платёжным организациям, хостинг- и иным поставщикам услуг. Полные данные банковской карты не хранятся на {store_domain} в открытом виде. Вопросы: {store_mail}."}, "ar-SA": {"title": "الخصوصية والأمان", "slug": "gizlilik-ve-guvenlik-ar", "body": "الخصوصية والأمان\n\nتعالج {store_name} البيانات الشخصية المقدمة عبر {store_domain}، بما في ذلك بيانات الهوية والاتصال والطلبات والاستخدام التقني، لتنفيذ الطلبات وخدمة العملاء والأمان والالتزامات القانونية، ولأغراض التسويق عند وجود أساس قانوني أو موافقة صالحة. لا يتم بيع البيانات. يمكن مشاركة البيانات اللازمة مع شركات الشحن ومزودي الدفع والاستضافة والخدمات عند الحاجة. لا يتم تخزين أرقام البطاقات الكاملة بشكل مقروء على أنظمة {store_domain}. للاستفسارات: {store_mail}."}}},
  {type:"RETURNS",slug:"tuketici-haklari-cayma-iptal-iade-kosullari",title:"Tüketici Hakları – Cayma – İptal İade Koşulları",body:"TÜKETİCİ HAKLARI – CAYMA – İPTAL İADE KOŞULLARI\n\nGENEL\n\nWeb sitesi üzerinden elektronik ortamda sipariş verdiğiniz takdirde size sunulan ön bilgilendirme formunu ve mesafeli satış sözleşmesini kabul etmiş sayılırsınız. Alıcılar, satın aldıkları ürünün satış ve teslimi ile ilgili olarak 6502 sayılı Tüketicinin Korunması Hakkında Kanun, Mesafeli Sözleşmeler Yönetmeliği ve yürürlükteki diğer mevzuata tabidir.\n\nÜrün sevkiyat masrafları, aksi kampanya veya sözleşme şartlarında belirtilmedikçe alıcı tarafından karşılanır. Satın alınan ürün, mevzuatta öngörülen süreleri aşmamak kaydıyla alıcının gösterdiği adrese teslim edilir ve siparişte belirtilen niteliklere uygun olmalıdır.\n\nSATIN ALINAN ÜRÜN BEDELİ ÖDENMEZ İSE\n\nAlıcı ürün bedelini ödemez veya ödeme banka kayıtlarında iptal edilirse, satıcının ürünü teslim yükümlülüğü sona erer.\n\nKREDİ KARTININ YETKİSİZ KULLANIMI\n\nÜrün tesliminden sonra ödeme aracının yetkisiz kişilerce kullanıldığı tespit edilir ve ürün bedeli satıcıya ödenmezse, mevzuat ve ilgili ödeme kuruluşu/banka prosedürleri uygulanır.\n\nÖNGÖRÜLEMEYEN SEBEPLERLE TESLİM\n\nSatıcının öngöremeyeceği mücbir sebepler oluşur ve ürün süresinde teslim edilemezse durum alıcıya bildirilir. Alıcı siparişin iptalini, uygun olduğu ölçüde benzer ürün ile değiştirilmesini veya teslimatın ertelenmesini talep edebilir.\n\nALICININ ÜRÜNÜ KONTROL ETMESİ\n\nAlıcının teslim sırasında ezik, kırık, ambalajı yırtılmış veya açıkça hasarlı ürünlerde kargo görevlisi ile tutanak tutması tavsiye edilir. Cayma hakkı kullanılacaksa ürün, niteliği gereği zorunlu kullanım dışında özenle korunmalıdır.\n\nCAYMA HAKKI\n\nALICI, satın aldığı ürünün kendisine veya gösterdiği adresteki kişi/kuruluşa teslim tarihinden itibaren kanuni süre içinde SATICI'ya bildirimde bulunarak, mevzuattaki istisnalar saklı kalmak kaydıyla cayma hakkını kullanabilir.\n\nSATICININ CAYMA HAKKI BİLDİRİMİ YAPILACAK İLETİŞİM BİLGİLERİ\n\nADI/UNVANI: {store_owner}\nADRES: {store_address}\nE-POSTA: {store_email}\nTEL: {store_telephone}\n\nCAYMA HAKKININ KULLANIMI VE İADE KOŞULLARI\n\nİade sürecinde fatura/elektronik fatura bilgileri, iade formu ve ürünle birlikte gelen kutu, ambalaj ve standart aksesuarların mevzuata uygun şekilde teslimi istenebilir. İade ve geri ödeme süreleri yürürlükteki tüketici mevzuatına göre uygulanır.\n\nCAYMA HAKKI KULLANILAMAYACAK ÜRÜNLER\n\nTüketicinin istekleri veya kişisel ihtiyaçları doğrultusunda hazırlanan mallar, çabuk bozulabilecek veya son kullanma tarihi geçebilecek mallar, tesliminden sonra ambalajı açılmış olması halinde iadesi sağlık ve hijyen açısından uygun olmayan mallar, elektronik ortamda anında ifa edilen hizmetler ve mevzuatta sayılan diğer istisnalar için cayma hakkı sınırlı veya kullanılamaz olabilir.\n\nTEMERRÜT HALİ VE HUKUKİ SONUÇLARI\n\nKredi kartı işlemlerinde kart sahibi ile banka arasındaki sözleşme hükümleri ve ilgili mevzuat uygulanır.\n\nÖDEME VE TESLİMAT\n\nMağazada aktif edilen ödeme ve teslimat seçenekleri checkout sırasında gösterilir. Ödeme işlemi, seçilen ödeme yöntemi ve sağlayıcı kurallarına göre tamamlanır.",translations:{"en-US": {"title": "Consumer Rights – Withdrawal, Cancellation and Returns", "slug": "consumer-rights-returns", "body": "CONSUMER RIGHTS – WITHDRAWAL, CANCELLATION AND RETURNS\n\nPurchases made through {store_domain} are subject to applicable Turkish consumer law, including Law No. 6502 and the Distance Contracts Regulation.\n\nRIGHT OF WITHDRAWAL\n\nUnless a statutory exception applies, consumers may exercise the right of withdrawal within the legal period by notifying the SELLER.\n\nSELLER CONTACT\nCompany/Name: {store_owner}\nAddress: {store_address}\nEmail: {store_email}\nPhone: {store_telephone}\n\nRETURN CONDITIONS\n\nReturn costs, refund periods, product condition and documentation are handled according to applicable consumer law and the conditions communicated before purchase. Products prepared to the consumer’s specifications, rapidly perishable products, certain hygiene products after unsealing, immediately performed digital services and other statutory exceptions may be excluded from the right of withdrawal."}, "de-DE": {"title": "Verbraucherrechte – Widerruf, Stornierung und Rückgabe", "slug": "tuketici-haklari-cayma-iptal-iade-kosullari-de", "body": "VERBRAUCHERRECHTE – WIDERRUF, STORNIERUNG UND RÜCKGABE\n\nBestellungen über {store_domain} unterliegen dem anwendbaren türkischen Verbraucherrecht, insbesondere Gesetz Nr. 6502 und den Vorschriften über Fernabsatzverträge. Sofern keine gesetzliche Ausnahme gilt, kann der Verbraucher sein Widerrufsrecht innerhalb der gesetzlichen Frist ausüben.\n\nVERKÄUFER: {store_owner}\nAdresse: {store_address}\nE-Mail: {store_email}\nTelefon: {store_telephone}\n\nRücksendung, Erstattung, Kosten und Ausnahmen werden nach den zwingenden gesetzlichen Vorschriften und den vor Vertragsschluss mitgeteilten Bedingungen behandelt."}, "ru-RU": {"title": "Права потребителей – отказ, отмена и возврат", "slug": "tuketici-haklari-cayma-iptal-iade-kosullari-ru", "body": "ПРАВА ПОТРЕБИТЕЛЕЙ – ОТКАЗ, ОТМЕНА И ВОЗВРАТ\n\nПокупки через {store_domain} регулируются применимым турецким законодательством о защите потребителей, включая Закон № 6502 и правила дистанционных договоров. Если законом не предусмотрено исключение, потребитель может воспользоваться правом отказа в установленный законом срок.\n\nПРОДАВЕЦ: {store_owner}\nАдрес: {store_address}\nE-mail: {store_email}\nТелефон: {store_telephone}\n\nУсловия возврата, сроки возмещения, расходы и предусмотренные законом исключения применяются в соответствии с обязательными нормами и информацией, сообщённой до покупки."}, "ar-SA": {"title": "حقوق المستهلك – العدول والإلغاء والإرجاع", "slug": "tuketici-haklari-cayma-iptal-iade-kosullari-ar", "body": "حقوق المستهلك – العدول والإلغاء والإرجاع\n\nتخضع المشتريات عبر {store_domain} لقانون حماية المستهلك التركي المعمول به، بما في ذلك القانون رقم 6502 ولائحة العقود عن بُعد. ما لم ينطبق استثناء قانوني، يمكن للمستهلك ممارسة حق العدول خلال المدة القانونية.\n\nالبائع: {store_owner}\nالعنوان: {store_address}\nالبريد الإلكتروني: {store_email}\nالهاتف: {store_telephone}\n\nتُطبق شروط الإرجاع ومدد رد المبالغ والتكاليف والاستثناءات وفقاً للقواعد الإلزامية والمعلومات المقدمة قبل الشراء."}}},
  {type:"TERMS",slug:"kullanim-kosullari",title:"Kullanım Koşulları",body:"{store_domain} web sitesi içinde yer alan yazı ve görsel malzemelerin hakları, aksi belirtilmedikçe {store_owner}'ye veya ilgili hak sahiplerine aittir. İzinsiz kullanım ve kopyalama yürürlükteki mevzuata tabidir.\n\nSözleşme Şart ve Hükümleri\n\n{store_domain} web sitesini kullanmakla aşağıdaki kullanım şartlarını kabul etmiş olursunuz. {store_name}, yürürlükteki mevzuata uygun olmak kaydıyla şartları güncelleyebilir; güncel metin yayınlandığı tarihten itibaren uygulanır.\n\nTelif Hakları\n\nBu sitede yer alan grafikler, resimler, logolar, yazılar ve diğer içerik öğeleri aksi belirtilmedikçe {store_domain} veya ilgili hak sahiplerine aittir. Site içeriğinin seçimi, hazırlanışı ve düzenlenmesine ilişkin haklar saklıdır.\n\nLisans\n\nSiteyi kişisel ve hukuka uygun amaçlarla kullanabilirsiniz. Site içeriğini yazılı izin olmaksızın kopyalamanız, dağıtmanız, yeniden yayınlamanız, satmanız veya ticari olarak çoğaltmanız yasaktır.\n\nBağlantılı Sayfalar\n\nSite üçüncü taraf internet sayfalarına bağlantılar içerebilir. {store_domain}, üçüncü tarafların sunduğu bilgi, ürün veya hizmetlerin doğruluğu ve güvenliğinden, kanunen sorumlu tutulması gereken haller dışında sorumlu değildir.\n\nYorumlar\n\nKullanıcılar tarafından gönderilen yorum ve içeriklerin hukuka ve genel ahlaka uygun olması gerekir. Hukuka aykırı kullanıcı içeriklerinden öncelikle içeriği oluşturan kişi sorumludur.\n\nKampanyalar\n\n{store_domain} üzerinde sunulan kampanyalar ilan edilen şartlar ve stoklar çerçevesinde geçerlidir. Kampanya koşullarında yapılacak değişiklikler tüketici mevzuatına uygun şekilde uygulanır.\n\nTekzip ve Sorumluluk\n\n{store_domain}, site içeriğini güncel ve doğru tutmak için makul özeni gösterir. Tipografik veya teknik hatalar fark edildiğinde düzeltilir. Tüketicinin emredici hakları saklıdır.\n\nGeçerli Hukuk\n\n{store_domain} Türkiye'de faaliyet gösteren bir mağazadır. Uyuşmazlıklarda Türkiye Cumhuriyeti hukuku ve görevli/yetkili tüketici mercilerine ilişkin emredici hükümler uygulanır.",translations:{"en-US": {"title": "Terms of Use", "slug": "terms-of-use", "body": "TERMS OF USE\n\nUnless otherwise stated, content on {store_domain} is owned by {store_owner} or the relevant rights holder. You may use the site for lawful personal purposes. Unauthorized copying, distribution or commercial reuse is prohibited.\n\nUsers must not disrupt the site, violate third-party rights, upload malicious code or use the service for unlawful purposes. Third-party links are provided for convenience and are governed by the third party’s own terms. Campaigns apply under their announced conditions and while stocks last. Mandatory consumer rights remain unaffected. Turkish law applies subject to mandatory jurisdiction rules."}, "de-DE": {"title": "Nutzungsbedingungen", "slug": "kullanim-kosullari-de", "body": "NUTZUNGSBEDINGUNGEN\n\nInhalte auf {store_domain} gehören, soweit nicht anders angegeben, {store_owner} oder den jeweiligen Rechteinhabern. Die Website darf nur rechtmäßig genutzt werden. Unerlaubtes Kopieren, Verbreiten, Schadsoftware, Eingriffe in den Betrieb und Verletzungen von Rechten Dritter sind untersagt. Zwingende Verbraucherrechte bleiben unberührt. Es gilt türkisches Recht unter Beachtung zwingender Zuständigkeitsregeln."}, "ru-RU": {"title": "Условия использования", "slug": "kullanim-kosullari-ru", "body": "УСЛОВИЯ ИСПОЛЬЗОВАНИЯ\n\nЕсли не указано иное, материалы {store_domain} принадлежат {store_owner} или соответствующим правообладателям. Сайт разрешено использовать только законным образом. Запрещены несанкционированное копирование и распространение, вредоносный код, нарушение работы сайта и прав третьих лиц. Обязательные права потребителя сохраняются. Применяется законодательство Турецкой Республики с учётом обязательных правил подсудности."}, "ar-SA": {"title": "شروط الاستخدام", "slug": "kullanim-kosullari-ar", "body": "شروط الاستخدام\n\nما لم يُذكر خلاف ذلك، تعود حقوق محتوى {store_domain} إلى {store_owner} أو أصحاب الحقوق المعنيين. يجب استخدام الموقع لأغراض مشروعة فقط. يُحظر النسخ أو التوزيع غير المصرح به، والبرمجيات الضارة، وتعطيل الخدمة، وانتهاك حقوق الغير. لا تتأثر حقوق المستهلك الإلزامية. يطبق قانون الجمهورية التركية مع مراعاة قواعد الاختصاص الإلزامية."}}},
  {type:"KVKK_NOTICE",slug:"kvkk-aydinlatma-metni",title:"Kişisel Verilerin İşlenmesine İlişkin Aydınlatma Metni",body:"KİŞİSEL VERİLERİN İŞLENMESİNE İLİŞKİN AYDINLATMA METNİ\n\n1- KİMLİK \n\nVeri Sorumlusu: {store_owner}\n\nVeri Sorumlusu olarak {store_owner} (Bundan sonra “{store_name}” şeklinde anılacaktır.) 6698 sayılı Kişisel Verilerin Korunması Kanunu (KVKK) ve ilgili mevzuat kapsamında; kişisel verilerinizin işlenmesi, saklanması ve aktarılması ile ilgili veri sahiplerini aydınlatmak amacıyla işbu aydınlatma metni hazırlanmış ve bilgilerinize sunulmuştur. (Lütfen dikkatli bir şekilde okuyunuz. Anlaşılmayan konularda bizlere yukarıda yazılı iletişim bilgilerinden ya da Başvuru Formu’ndan ulaşabilirsiniz.) \n\n2- KAPSAM: \n\n{store_name} olarak; müşterilerimiz, ziyaretçilerimiz, tedarikçilerimiz ve çalışanlarımız dahil gerçek kişilerin kişisel verilerinin başta Anayasa’mız ve 6698 sayılı Kişisel Verilerin Korunması Kanunu olmak üzere uluslararası sözleşmeler, Türk Kanun ve yönetmeliklerine uygun olarak işlenmesi ve verisi işlenen ilgili kişilerin haklarını etkin şekilde kullanmasının sağlanmasına çalışarak işbu aydınlatma metnini oluşturarak bilgilerinize sunmaktayız. Bu nedenle, sayılanlarla sınırlı olmamak üzere; başta siz değerli danışanlarımız olmak üzere, çalışanlarımızın, tedarikçilerimizin, müşterilerimizin ve internet sitemizi ziyaret eden kullanıcılarımızın, kısacası faaliyetlerimiz sırasında edindiğimiz sözlü ve yazılı veya elektronik ortamdaki tüm kişisel verilere ilişkin verinin işlenmesi, saklanması, aktarılmasına ve ilgili kişi olarak haklarınıza ilişkin işlemleri {store_name} Kişisel Verilerin Korunması ve İşlenmesine yönelik GİZLİLİK ve ÇEREZ POLİTİKASI’na göre gerçekleştirmekteyiz. \n\nKişisel verilerin korunması için mevzuat ve güncel teknolojiye uygun şekilde ilgili verinin niteliğinin gerektirdiği tüm idari ve teknik koruma tedbirlerini almaktayız. \n\n3- TANIMLAR:  \n\nKVKK: 6698 Sayılı Kişisel Verilerin Korunması Kanunu \n\na) Kişisel veri: Kimliği belirli veya belirlenebilir gerçek kişiye ilişkin her türlü bilgiyi, \n\nb) Açık rıza: Belirli bir konuya ilişkin, bilgilendirilmeye dayanan ve özgür iradeyle açıklanan rızayı, \n\nc) Anonim hâle getirme: Kişisel verilerin, başka verilerle eşleştirilerek dahi hiçbir surette kimliği belirli veya belirlenebilir bir gerçek kişiyle ilişkilendirilemeyecek hâle getirilmesini,\n\nç) İlgili kişi: Kişisel verisi işlenen gerçek kişiyi, \n\nd) Kişisel veri: Kimliği belirli veya belirlenebilir gerçek kişiye ilişkin her türlü bilgiyi, \n\ne) Kişisel verilerin işlenmesi: Kişisel verilerin tamamen veya kısmen otomatik olan ya da herhangi bir veri kayıt sisteminin parçası olmak kaydıyla otomatik olmayan yollarla elde edilmesi, kaydedilmesi, depolanması, muhafaza edilmesi, değiştirilmesi, yeniden düzenlenmesi, açıklanması, aktarılması, devralınması, elde edilebilir hâle getirilmesi, sınıflandırılması ya da kullanılmasının engellenmesi gibi veriler üzerinde gerçekleştirilen her türlü işlemi, \n\nf) Kurul: Kişisel Verileri Koruma Kurulunu,\n\ng) Kurum: Kişisel Verileri Koruma Kurumunu,\n\n4-İLKELERİMİZ \n\nİşbu Politika, ticari veya sosyal sorumluluk ve benzeri faaliyetlerimiz sırasında paylaşılan kişisel verilerin 6698 Sayılı Kişisel Verilerin Korunması Kanunu‘nda öngörülen usul ve esaslar çerçevesinde ve:\n\na) Hukuka ve dürüstlük kurallarına uygun olarak\n\nb) Doğru ve gerektiğinde güncel olmasına dikkat ederek.\n\nc) Belirli, açık ve meşru amaçlarla\n\nç) İşlendikleri amaçla bağlantılı, sınırlı ve ölçülülük esasları ile .\n\nd) İlgili mevzuatta öngörülen veya işlendikleri amaç için gerekli olan süre kadar muhafaza edilmeleri İlkeler çerçevesinde işlenmesi, saklanması, aktarılması ve silinmesi ya da anonim hale getirilmesine dair izlediğimiz yöntemleri açıklamakta ve kapsamaktadır.\n\n5- İŞLENEN KİŞİSEL VERİLER VE İŞLEME AMAÇLARIMIZ:\n\n5,1.  KVKK 5. Maddesi uyarınca, Kişisel veriler, ilgili kişinin açık rızası olmaksızın işlememekteyiz. \n\nKişisel verilerin işlenmesinde başta özel hayatın gizliliği olmak üzere kişilerin temel hak ve özgürlüklerini koruyarak ve kişisel verileri sorumlusu sıfatı ile AÇIK RIZA alınarak, aşağıda belirttiğimiz amaçlarla işlemekteyiz: \n\nÜrün ve hizmetlerin satış süreçlerinin planlanması, yürütülmesi, satış sonrası destek hizmetleri aktivitelerinin planlanması, yürütülmesi, üye/kullanıcı/danışan ilişkileri yönetimi süreçlerinin planlanması, yürütülmesi, üye/kullanıcı/danışan talep veya şikâyetlerinin takibi ve sonuçlandırılması, sözleşme süreçlerinin ve hukuki taleplerin takibi için, Personelimiz,  ya da çağrı merkezi standartları gereği tutulan sesli görüşme kayıtlarınız ile elektronik posta veya sair vasıtalar aracılığı ile tarafımızla iletişime geçtiğinizde elde edilen kişisel verileriniz; Kimlik Bilgilerinize ait : adınız, soyadınız, T.C. kimlik numaranız, doğum yeri ve tarihiniz, medeni haliniz, cinsiyetiniz ve sizi tanımlayabileceğimiz diğer kimlik verileriniz ve İletişim Bilgileriniz; adresiniz, telefon numaranız, elektronik posta adresiniz ve sair iletişim kurabilmemiz adına gerekli diğer bilgileriniz  \n\n{store_name}’ten aldığınız ürün veya hizmet sırasında satın aldığınız ürün veya hizmet ödemesinin tahsili, ürünün gönderilmesi, işlem güvenliği, bu sebeple  kurulan hukuki ilişkiden kaynaklanan yükümlülüklerin ifası, Finans, muhasebe, sigorta, hukuk ve vergi işlerinin takibi ve koordinasyonu,  pazarlama, reklam, dönemsel kampanya çalışmaları, ve istenmeyen e-postaların iletilmemesine yönelik müşteri \"sınıflandırma” çalışmalarında, müşteri profil ve davranış sınıflandırmalarında, müşteri memnuniyet şikayetlerinin değerlendirilmesi ve analiz faaliyetleri, hedefleme, strateji ve verimlilik çalışmalarının yapılması, amacıyla muhasebesel bilgilerinize ait; banka hesap numaranız, IBAN numaranız, kredi kartı bilginiz, faturalama bilgileriniz gibi finansal verileriniz ya da çağrı merkezi standartları gereği tutulan sesli görüşme kayıtlarınızda verdiğiniz sair finansal verileriniz; ve Kimlik Bilgilerinize ait;  adınız, soyadınız, T.C. kimlik numaranız, doğum yeri ve tarihiniz, medeni haliniz, cinsiyetiniz ve sizi tanımlayabileceğimiz diğer kimlik bilgileriniz\n\nKurumsal iletişim, lojistik, depolama faaliyetlerinin; Üretim, tedarik ve Üye/kullanıcı/danışan memnuniyetinin sağlanması, aktivitelerinin planlanması, yürütülmesi, \n\n{store_name} tarafından sunulan ürün ve hizmetlerden ilgili kişileri faydalandırmak için gerekli çalışmaların iş birimlerimiz tarafından yapılması ve ilgili iş süreçlerinin yürütülmesi kapsamında, ürün ve hizmetlerin satış süreçlerinin planlanması, yürütülmesi, satış sonrası destek hizmetleri aktivitelerinin planlanması, yürütülmesi, üye/kullanıcı/danışan talep veya şikâyetlerinin takibi ve sonuçlandırılması, sözleşme süreçlerinin ve hukuki taleplerin takibi,\n\nYetkili kuruluşlara mevzuattan kaynaklı bilgi verilmesi, \n\nBilgi güvenliği süreçlerinin planlanması, denetimi ve yürütülmesi, bilgi teknolojileri alt yapısının oluşturulması, yönetilmesi ve kontrolü, \n\nSosyal medya, yazılı-sözlü ve internet medyası, arama motorları vb. farklı kanallarda pazarlama faaliyetlerinin yürütülmesi, müşterilere genel ve özel nitelikte teklifler, ürünler ve hizmetler sunulması ve bu kapsamda çağrı merkezinin hizmetlerinden faydalanılması, müşteri/danışan ile yapılan telefon görüşmelerinin kalitesinin ölçülmesi ve değerlendirilmesi ile yasal ve sözleşmeden doğan yükümlülüklerimizin ifasını sağlamak, amaçları ile KVKK’nın 5. ve 8. maddeleri uyarınca ve/veya ilgili mevzuattaki istisnaların varlığı halinde kişisel verileriniz rızanız doğrultusunda, veya İlgili kanunda belirtilen hallerde rızanız alınmaksızın yukarıdaki amaçlar doğrultusunda kişisel verileriniz ve özel nitelikli kişisel verileriniz işlenecektir. \n\n5,2 Özel nitelikli kişisel verilerin işlenmesi ve şartları \n\n6698 Sayılı KVKK 6. Madde uyarınca; Kişilerin ırkı, etnik kökeni, siyasi düşüncesi, felsefi inancı, dini, mezhebi veya diğer inançları, kılık ve kıyafeti, dernek, vakıf ya da sendika üyeliği, sağlığı, cinsel hayatı, ceza mahkûmiyeti ve güvenlik tedbirleriyle ilgili verileri ile biyometrik ve genetik verileri özel nitelikli kişisel veridir. Özel nitelikli kişisel verileri, ilgilinin açık rızası olmaksızın işlememekteyiz.\n\nİSTİSNA: \n\nAncak işbu aydınlatma metni 5,2 bendinde sayılan sağlık ve cinsel hayat dışındaki kişisel veriler, kanunlarda öngörülen hâllerde ilgili kişinin açık rızası aranmaksızın işlenebilir. Sağlık ve cinsel hayata ilişkin kişisel veriler ise ancak kamu sağlığının korunması, koruyucu hekimlik, tıbbî teşhis, tedavi ve bakım hizmetlerinin yürütülmesi, sağlık hizmetleri ile finansmanının planlanması ve yönetimi amacıyla, sır saklama yükümlülüğü altında bulunan kişiler veya yetkili kurum ve kuruluşlar tarafından ilgilinin açık rızası aranmaksızın işlenebilir. \n\n6- HUKUKİ DAYANAK: \n\nKişisel verileriniz, {store_name} tarafından yukarıda sayılan amaçların gerçekleştirilmesi doğrultusunda, Başta Anayasamız olmak üzere, Uluslararası kanun ve Mevzuatlar, Türkiye Cumhuriyeti Kanun, Tüzük ve Yönetmelikleri ve bu metnin asıl dayanağı olan 6698 sayılı Kişisel Verilerin Korunması Kanunu’nun 5’inci ve 6’ncı maddelerinde belirtilen; kişisel veri işleme şartları ve amaçları dâhilinde \n\nAçık rıza alınarak,\n\nKanunlarda açıkça öngörülmesi,\n\nFiili imkânsızlık nedeniyle rızasını açıklayamayacak durumda bulunan veya rızasına hukuki geçerlilik tanınmayan kişinin kendisinin ya da bir başkasının hayatı veya beden bütünlüğünün korunması için zorunlu olması hallerinde, \n\nBir sözleşmenin kurulması veya ifasıyla doğrudan doğruya ilgili olması kaydıyla, sözleşmenin taraflarına ait kişisel verilerin işlenmesinin gerekli olması durumlarında, \n\nVeri sorumlusunun hukuki yükümlülüğünü yerine getirebilmesi için zorunlu olması halinde,\n\nİlgili kişinin kendisi tarafından alenileştirilmiş olması,\n\nBir hakkın tesisi, kullanılması veya korunması için veri işlemenin zorunlu olması,\n\nİlgili kişinin temel hak ve özgürlüklerine zarar vermemek kaydıyla, veri sorumlusunun meşru menfaatleri için veri işlenmesinin zorunlu olması hallerinde, \n\nVe 6. Maddesinin 2. Fıkrasında belirtilen “Açık rıza” ve 3. Fıkrasında belirtilen “Özel nitelikli kişisel verilerin, sağlık ve cinsel hayat dışında kalanlarının kanunlarda ön görülen hallerde açık rıza alınmadan işlenebilmesine dayanmaktadır.\n\n7- KİŞİSEL VERİLERİN AKTARILABİLECEK KİŞİLER VE AKTARIM AMACI:\n\n7,1. Öncelikle, Mevzuatta yer alan istisnai haller saklı kalmak kaydıyla, kişisel veriler ve özel nitelikli veriler ilgili kişinin açık rızası olmadan başka gerçek kişilere ve tüzel kişilere tarafımızca aktarılmayacağını belirtmek isteriz.\n\nİlgili kişinin açık rızası halinde: Bize aktardığınız yukarıda yazılı amaçlarla ve vasıtalarla işlenen kişisel verilerinizi, aşağıda yazılı gereklilik kapsamında ve belirtilen kişi/kurum/kuruluşlara ile paylaşılabilecektir. \n\nİşbu kapsamda:  \n\n{store_name} müşterilerine daha kaliteli hizmet sunmak, bu hizmetlere daha kolay ulaşmalarını sağlamak adına; İnsan kaynakları servisimiz, ilgili personelimiz ve verdiğimiz hizmetlere ek ve tamamlayıcı hizmetler talebiniz halinde, partner kurum/kuruluşlarımız ve uzmanlarımız ile   \n\n{store_name} adına veri işleyen, müşteri memnuniyeti ölçümleme, profilleme desteği veren, satış ve pazarlama alanında kişisel verilerin işlenmesi gereken konularda destek veren; reklam, tanıtım ve promosyon faaliyetlerinin yürütülmesi amaçları ile, {store_name}’in iş ortakları, depolama, arşivleme ve sunucu, hosting, program, bulut bilişim teknolojileri desteği, bilişim güvenliği gibi alanlarda destek aldığımız üçüncü kişilerle, \n\n{store_name}’ten Web sitesi üzerinden ilgili formu doldurarak bizlerden hizmet satın aldığınız hallerde, size ulaşabilmemiz adına isim, telefon numarası ve adres bilgileri ulusal ve uluslararası kargo firmaları ile \n\n\nMesafeli satış işlemlerinde ödemelerinizin gerçekleştirilebilmesi için ulusal ve uluslararası banka, finans ve ödeme kuruluşları ile \n\n\n{store_name} ile iş ilişkisi içerisinde olan ilgili kişilerin; hukuki, teknik ve ticari iş güvenliğinin ve haklarının temin edilmesi ve {store_name} tarafından sunulan ürün ve hizmetlerden ilgili kişileri faydalandırmak için gerekli çalışmaların ilgili departmanlarımızca yapılması ve ilgili iş süreçlerinin yürütülmesi amaçlarıyla; KVKK’nın 8. ve 9. maddelerinde belirtilen kişisel veri işleme şartları ve amaçları çerçevesinde sayılanlar ile sınırlı olmamak üzere; iştiraklerimize, hissedarlarımıza, iş ortaklarımıza, ilgili personelimize ve kanunen yetkili kamu kurumları ve özel kişiler ile diğer kişilerle, ifa yardımcılarımız ve alt yüklenicilerimiz ile sunduğumuz hizmetin amacı doğrultusunda ya da düzenleyici denetleyici kurumlar ve resmi mercilerle ilgili mevzuatın öngördüğü durumlarda yurt içine veya yurt dışına aktarılabilecektir. \n\n7,2 {store_name}, web sitesi üzerinden veya fiziki alarak danışan ve üyelerinden, üyelik formlarından topladığı bilgileri, yasal zorunluluklar ve yükümlülükler haricinde, söz konusu üyenin haberi ya da aksi bir talimatı olmaksızın, üçüncü şahıslarla kesinlikle paylaşmamakta, faaliyet dışı hiçbir nedenle ticari amaçla kullanmamakta ve de satmamaktadır.\n\nBilgileriniz, ancak resmi makamlarca hukuki bir ihtiyaç talebi ile bu bilgilerin talep edilmesi halinde ve yürürlükteki emredici mevzuat hükümleri usul ve esasları gereğince resmi makamlara açıklama yapmak zorunda olduğu durumlarda sizin bilginiz haricinde aktarılabilecektir.\n\nÖdeme sayfasında istenen kredi kartı bilgileriniz, güvenliğini en üst seviyede tutmak amacıyla hiçbir şekilde {store_name}’ten veya ona hizmet veren şirketlerin sunucularında tutulmamaktadır. Bu şekilde ödemeye yönelik tüm işlemlerin {store_name} arayüzü üzerinden banka, bu bankalarla anlaşmalı aracı kurum ve bilgisayarınız arasında gerçekleşmesi sağlanmaktadır. Tarafımızda saklanan kredi kartı numarası maskelenmiş şekildedir\n\n8- VERİ SAHİBİ (İLGİLİ KİŞİ)’NİN HAKLARI: \n\n8,1 KVKK md.11 kapsamında kişisel verilerinize ilişkin olarak;\n\nKişisel verilerinizin işlenip işlenmediğini öğrenme,\n\nKişisel verileriniz işlenmişse buna ilişkin bilgi talep etme,\n\nKişisel verilerin işlenme amacını ve bunların amacına uygun kullanılıp kullanılmadığını öğrenme,\n\nYurt içinde veya yurt dışında kişisel verilerinizin aktarıldığı üçüncü kişileri bilme,\n\nKişisel verilerinizin eksik veya yanlış işlenmiş olması halinde bunların düzeltilmesini isteme,\n\nKVKK mevzuatında öngörülen şartlar çerçevesinde kişisel verilerinizin silinmesini veya yok edilmesini isteme,\n\nEksik veya yanlış verilerin düzeltilmesi ile kişisel verilerinizin silinmesi veya yok edilmesini talep ettiğinizde, bu durumun kişisel verilerinizi aktardığımız üçüncü kişilere bildirilmesini isteme,\n\nİşlenen verilerin münhasıran otomatik sistemler vasıtasıyla analiz edilmesi suretiyle kişinin kendisi aleyhine bir sonucun ortaya çıkmasına itiraz etme, \n\nKişisel verilerin kanuna aykırı olarak işlenmesi sebebiyle zarara uğramanız halinde bu zararın giderilmesini talep etme haklarına sahipsiniz. \n\n8.2 Haklarınızı Nasıl Kullanabilirsiniz?\n\nKişisel verileriniz ile ilgili başvuru ve taleplerinizi dilerseniz KVK Başvuru Formu (daha detaylı bilgi için lütfen tıklayınız.) aracılığıyla; Islak imzalı dilekçe ve kimlik fotokopisi ile {store_address} adresine bizzat veya posta yolu başvurarak bizlere ulaştırabilirsiniz \n\nYa da İlgili kişi tarafından {store_name} daha önce bildirilen ve sistemimizde kayıtlı bulunan elektronik posta adresinden {store_email}  e-mail adresimize gönderebilirsiniz.\n\n9- KİŞİSEL VERİLERİN GÜVENLİĞİ:\n\n\nVeri Sorumlusu olarak Kişisel verilerin güvenliğine ilişkin yükümlülüklerimiz:\n\nKişisel verilerin;\n\nHukuka aykırı işlenmesini önlemek,\n\nHukuka aykırı erişimini önlemek,\n\nHukuka uygun olarak saklanmasını sağlamak için teknolojik olanaklar ve uygulama maliyetlerine göre idari ve teknik tedbirler almaktayız. \n\nBu tedbirler: \n\n9,1- Teknik tedbirler:\n\nKişisel verilerin silinmesi, yok edilmesi ve anonimleştirilmesi için teknik alt yapılar ve bunlara ilişkin denetim mekanizmaları oluşturarak,\n\nTeknik/teknolojik uzmanlığı olan çalışanlar istihdam ederek,\n\nOluşabilecek risklere karşı iş sürekliliği ve acil durum planları oluşturup bunların uygulanmasına ilişkin yazılımsal sistemler kullanarak, güvenlik sistemleri kurarak kişisel verilerin güvenli şekilde saklanması için gerekli tedbirleri almaktayız. \n\n\n9,2- İdari tedbirler:\n\nÇalışanlarımızı KVKK ile ilgili üst seviyede eğitim programlarına dahil ederek bu konuda ilgili teknik ve idari riskler hakkında bilgilendirerek farkındalık yaratmaktayız.\n\nÜçüncü kişilerle yaptığımız iş birliklerinde ve Kişisel verilerin saklanması için kişisel verilerin aktarıldığı şirketler ile yapılan sözleşmelere; kişisel verilerin aktarıldığı kişilerin, aktarılan kişisel verilerin korunması ve güvenli saklanması amacıyla gerekli güvenlik tedbirlerinin alınmasına ilişkin hükümlere mutlaka yer vermekteyiz ve konuyla ilgili taahhütname imzalamaktayız.  \n\n10- İŞLENEN KİŞİSEL VERİLERİN SİLİNMESİ, YOK EDİLMESİ, ANONİM HALE GETİRİLMESİ\n\nVeri sorumlusu {store_name} olarak yukarıda açıklanan amaç ve yöntemlerle elde edilen kişisel verileriniz 6698 sayılı Kişisel Verilerin Korunması Kanunu ve ilgili diğer kanun hükümlerine uygun olarak işlenmiş olmasına rağmen, işlenmesini gerektiren sebeplerin ortadan kalkması durumunda ilgili kanunlarda belirtilen zorunlu saklama süreleri bitiminde kişisel veriler, re’sen veya ilgili kişinin talebi üzerine veri sorumlumuz tarafından silinir, yok edilir veya anonim hâle getirilir.\n\n10,1 Periyodik İmha Dönemi\n\nSaklama süresi dolan kişisel veriler, saklama süresinin bitimini takip eden ilk periyodik imha zamanında imha edilir.\n\nSüresi sona eren ve kişisel verinin saklanmasını gerektirecek başka herhangi bir veri işleme amacı mevcut olmayan kişisel verileri, saklama sürelerinin sona ermesini takiben 4 ay içerisinde veri sorumlumuz tarafından anonim hale getirilir.\n\nAncak veri sorumlusunun meşru menfaatinin olduğu durumlarda, işlenme amacının ve ilgili kanunlarda belirtilen sürelerin de sona ermesine rağmen veri sahiplerinin temel hak ve özgürlüklerine zarar vermemek kaydıyla ve bu hak ve özgürlüklerin karşılıklı korumasının sağlanması amacıyla kişisel veriler, Borçlar Kanunu’nda düzenlenen genel 10 yıl olarak belirlenen zamanaşımı süresinin sona ermesine kadar saklanabilecektir. Söz konusu zamanaşımı süresinin sona ermesinin ardından kişisel veriler, Gizlilik Politikamız’da belirlenen prosedüre göre silinecek, yok edilecek yahut anonim hale getirilecektir.\n\n10,2 Kişisel Verilerinizin İşlenmesine İlişkin Talepleriniz Ne Kadar Sürede Cevaplanır?\n\nKişisel verilerinize ilişkin hak talepleriniz değerlendirilerek, bize ulaştığı tarihten itibaren en geç 30 gün içerisinde cevaplanır. Başvurunuzun olumsuz değerlendirilmesi halinde gerekçeli ret sebepleri başvuruda belirttiğiniz adrese elektronik posta veya posta yolu başta olmak üzere İlgili Kişi Başvuru Formu’nda seçilen usullerden biri ile gönderilir.\n\n11- COOKİE (ÇEREZ POLİTİKASI) \n\n{store_name} yukarıda yazılan kanunlar ve amaç doğrultusunda {store_name} sayfalarında cookie (çerez) kullanmaktadır. (daha ayrıntılı bilgi için “Çerez Politikası” metnini tıklayınız.) Bu kapsamda kullanıcılarının IP adresi, hangi sayfaları ziyaret ettiği, domain tipi, tarayıcı (browser) tipi, görüntülenen sayfa sayısı, ziyaret süresi ve hedef tamamlama sayısı gibi metrikleri temel alan yeniden pazarlama listeleri tanımlama, tarih ve saat gibi bilgilerini de istatistiki değerlendirme ve kişiye yönelik hizmetler ve teklifler sunma gibi amaçlarla kullanabilir. Ayrıca {store_name} sizlere daha kaliteli hizmet sunmak amacıyla, araştırmalar yapmak, veri tabanı oluşturmak ve pazar araştırmaları yapmak için iş birliği içinde olduğu firmalara Kullanıcı bilgilerini aktarabilir ve bu firmalar tarafından yukarıda sayılan amaçlarla sınırlı olarak Kullanıcı bilgileri işleyebilecektir. Daha sonra bu kullanıcıya sitede ya da Görüntülü Reklam Ağı’ndaki diğer sitelerde, kullanıcıların ilgi alanlarına göre hedefe yönelik reklam içeriği gösterebilir. \n\n\n13- {store_name} GDPR POLİTİKASI:\n\nGDPR NEDİR ? : Genel Veri Koruma Yönetmeliği (GDPR - General Data Protection Regulation) Avrupa genelinde AB vatandaşlarının kişisel verilerini korumaya yönelik oluşturulmuş yönetmeliktir. 25 Mayıs 2018 tarihinden itibaren Avrupa Birliği'ne üye ülkelerde yürürlüğe giren GDPR, Avrupa Birliği'ne üye ülkelerde büyük kurum ve kuruluşlarda var olan kişisel verilerin yönetmelikte belirtilen kurallar çerçevesinde güvenliğini sağlamayı konu edinmektedir.\n\nBu konuyla ilgili detaylı bilgi için “GDPR Aydınlatma Metni”ne tıklayınız.\n\nKVKK kapsamında “Veri Sorumlusu” sıfatıyla tüm ilgili kişilerin bilgisine saygılarımızla arz ederiz\n\n\"Başvuru Formu\" için tıklayınız  “Gizlilik ve Kullanma koşulları” için tıklayınız\n\nVeri Sorumlusu: {store_owner}",translations:{"en-US": {"title": "Personal Data Processing Information Notice", "slug": "personal-data-notice", "body": "PERSONAL DATA PROCESSING INFORMATION NOTICE\n\nData Controller: {store_owner}\n\n{store_name} processes personal data in accordance with Turkish Law No. 6698 on the Protection of Personal Data (KVKK) and applicable legislation. Data may include identity, contact, order, transaction, payment-related, customer service, security and technical usage information.\n\nPurposes include providing and delivering products and services, managing membership and orders, customer support, accounting and legal obligations, information security, fraud prevention, analytics and marketing where permitted by law or consent. Data may be transferred to authorized public bodies, payment and financial institutions, shipping companies, hosting/cloud and technology providers, professional advisers and service providers when necessary and lawful.\n\nUnder Article 11 of the KVKK, data subjects may request information about processing, correction, deletion or destruction where conditions are met, information on recipients, objection to certain automated results and compensation for unlawful processing. Requests can be sent to {store_address} or {store_email} using legally accepted methods.\n\nAppropriate technical and administrative security measures are applied. Data is retained only for periods required by the processing purpose and applicable law, then deleted, destroyed or anonymized as appropriate."}, "de-DE": {"title": "Informationshinweis zur Verarbeitung personenbezogener Daten", "slug": "kvkk-aydinlatma-metni-de", "body": "INFORMATIONSHINWEIS ZUR VERARBEITUNG PERSONENBEZOGENER DATEN\n\nVerantwortlicher: {store_owner}\n\n{store_name} verarbeitet personenbezogene Daten nach dem türkischen Gesetz Nr. 6698 (KVKK) und der einschlägigen Gesetzgebung. Zu den Daten können Identitäts-, Kontakt-, Bestell-, Zahlungs-, Support-, Sicherheits- und technische Nutzungsdaten gehören. Zwecke sind insbesondere Vertragsabwicklung, Lieferung, Kundenservice, Buchhaltung, rechtliche Pflichten, Informationssicherheit, Betrugsprävention, Analyse und – bei zulässiger Rechtsgrundlage – Marketing.\n\nDaten können, soweit erforderlich und rechtmäßig, an Behörden, Zahlungs- und Finanzinstitute, Versandunternehmen, Hosting-/Cloud-/IT-Anbieter, Berater und sonstige Auftragsverarbeiter weitergegeben werden. Betroffene können die Rechte nach Art. 11 KVKK über {store_address} oder {store_email} geltend machen."}, "ru-RU": {"title": "Уведомление об обработке персональных данных", "slug": "kvkk-aydinlatma-metni-ru", "body": "УВЕДОМЛЕНИЕ ОБ ОБРАБОТКЕ ПЕРСОНАЛЬНЫХ ДАННЫХ\n\nОператор данных: {store_owner}\n\n{store_name} обрабатывает персональные данные в соответствии с турецким Законом № 6698 (KVKK) и применимым законодательством. Могут обрабатываться идентификационные, контактные, заказные, платёжные, сервисные, технические и данные безопасности. Цели включают исполнение заказов, доставку, поддержку, бухгалтерский учёт, юридические обязанности, информационную безопасность, предотвращение мошенничества, аналитику и разрешённый маркетинг.\n\nВ необходимых и законных случаях данные могут передаваться государственным органам, банкам и платёжным организациям, службам доставки, облачным/IT-поставщикам, консультантам и иным поставщикам услуг. Права по статье 11 KVKK можно реализовать через {store_address} или {store_email}."}, "ar-SA": {"title": "إشعار معالجة البيانات الشخصية", "slug": "kvkk-aydinlatma-metni-ar", "body": "إشعار معالجة البيانات الشخصية\n\nمسؤول البيانات: {store_owner}\n\nتعالج {store_name} البيانات الشخصية وفقاً للقانون التركي رقم 6698 بشأن حماية البيانات الشخصية (KVKK) والتشريعات ذات الصلة. قد تشمل البيانات الهوية والاتصال والطلبات والدفع وخدمة العملاء والأمان والاستخدام التقني. تشمل الأغراض تنفيذ العقود والتسليم والدعم والمحاسبة والالتزامات القانونية وأمن المعلومات ومنع الاحتيال والتحليلات والتسويق المسموح به.\n\nعند الضرورة وبشكل قانوني، يمكن نقل البيانات إلى الجهات الرسمية والمؤسسات المالية ومزودي الدفع والشحن والاستضافة والسحابة وتقنية المعلومات والمستشارين ومزودي الخدمات. يمكن ممارسة الحقوق المنصوص عليها في المادة 11 من KVKK عبر {store_address} أو {store_email}."}}},
  {type:"DISTANCE_SALES",slug:"mesafeli-satis-sozlesmesi",title:"Mesafeli Satış Sözleşmesi",body:"MADDE 1 – TARAFLAR\n\n\n1.1 – SATICI\n\nÜnvanı : {store_owner}\n\nAdresi : {store_address}\n\nTelefon : {store_telephone}\n\nEposta adresi : {store_email}\n\n1.2 – ALICI\n\nMüşteri olarak {store_domain} alışveriş sitesine üye olan kişi.\n\nÜye olurken veya alışverişde kullanılan adres ve iletişim bilgileri esas alınır.\n\nMADDE 2 – KONU\n\nİşbu sözleşmenin konusu, ALICI’nın SATICI’ya ait {store_domain} İnternet sitesinden elektronik ortamda siparişini yaptığı aşağıda nitelikleri ve satış fiyatı belirtilen ürünün satışı ve teslimi ile ilgili olarak 6502 sayılı Tüketicilerin Korunması Hakkındaki Kanun ve Mesafeli Sözleşmeler Uygulama Esas ve Usulleri Hakkında Yönetmelik hükümleri gereğince tarafların hak ve yükümlülüklerinin saptanmasıdır.\n\nMADDE 3 – SÖZLEŞME KONUSU ÜRÜN\n\nMalın/ Ürünün / Hizmetin türü, miktarı, marka/modeli, rengi, adedi, satış bedeli, ödeme şekli, siparişin sonlandığı andaki bilgilerden oluşmaktadır\n\nMADDE 4 – GENEL HÜKÜMLER\n\n4.1 ALICI, {store_domain} internet sitesinde sözleşme konusu ürünün temel nitelikleri, tüm vergiler dahil satış fiyatı ve ödeme şekli ile teslimata ve bunun masraflarının ALICI tarafından karşılanacağına, teslimatın gerçekleştirileceği süreye ve SATICI’nın tam ticari unvanı, açık adresi ve iletişim bilgilerine ilişkin ön bilgileri okuyup bilgi sahibi olduğunu ve elektronik ortamda gerekli teyidi verdiğini beyan eder.\n\nALICI; bu sözleşmeyi elektronik ortamda teyit etmekle, mesafeli sözleşmelerin akdinden önce, Satıcı tarafından Tüketici’ye verilmesi gereken adres, siparişi verilen ürünlere ait temel özellikler, ürünlerin vergiler dahil fiyatı, ödeme ve teslimat bilgilerini de doğru ve eksiksiz olarak edindiğini teyid etmiş olur.\n\n4.2 Sözleşme konusu ürün, yasal 30 günlük süreyi aşmamak koşulu ile her bir ürün için ALICI’nın yerleşim yerinin uzaklığına bağlı olarak internet sitesinde ön bilgiler içinde açıklanan süre içinde ALICI veya gösterdiği adresteki kişi/kuruluşa teslim edilir. Madde 3’te gösterilen teslimata ilişkin her türlü kargo ücreti ALICI tarafından karşılanacak olup siparişine ilişkin faturasına “Gönderim Ücreti” adı altında yansıtılacaktır.\n\n4.3 Sözleşme konusu ürün, ALICI’dan başka bir kişi/kuruluşa teslim edilecek ise, teslim edilecek kişi/kuruluşun teslimatı kabul etmemesinden SATICI sorumlu tutulamaz.\n\n4.4 Kargo firmasının, ürünü ALICI’ya teslimi aşamasında karşılaşacağı her türlü sorun nedeniyle, siparişi verilen ürünün ALICI’ya teslim edilememesinden dolayı SATICI sorumlu tutulamaz.\n\n4.5 SATICI, sözleşme konusu ürünün sağlam, eksiksiz, siparişte belirtilen niteliklere uygun ve varsa garanti belgeleri ve kullanım kılavuzları ile teslim edilmesinden sorumludur.\n\n4.6 SATICI, haklı bir sebebe dayanmak şartıyla, sözleşmeden doğan ifa yükümlülüğünün süresi dolmadan ALICI’ya eşit kalite ve fiyatta farklı bir ürün tedarik edebilir.\n\n4.7 SATICI, sipariş konusu ürün veya hizmetin yerine getirilmesinin imkansızlaşması halinde sözleşme konusu yükümlülüklerini yerine getiremezse, bu durumu, sözleşmeden doğan ifa yükümlülüğünün süresi dolmadan tüketiciye bildirir ve ALICI’ya eşit kalite ve fiyatta farklı bir ürün tedarik edebilir.\n\n4.8 Sözleşme konusu ürünün teslimatı için işbu sözleşmenin imzalı nüshasının SATICI’ya ulaştırılmış olması ve bedelinin ALICI’nın tercih ettiği ödeme şekli ile ödenmiş olması şarttır. Herhangi bir nedenle ürün bedeli ödenmez veya banka kayıtlarında iptal edilir ise, SATICI ürünün teslimi yükümlülüğünden kurtulmuş kabul edilir.\n\n4.9 ALICI alışveriş esnasında sisteme tanımladığı kredi kartı bilgilerinin doğru olduğunu, bu kredi kartının kullanımından dolayı kaynaklanacak her türlü hukuki ve cezai yasal sorumluluğunun kendisinde olduğunu kabul ve taahhüt eder. Ürünün tesliminden sonra ALICI’ya ait kredi kartının ALICI’nın kusurundan kaynaklanmayan bir şekilde yetkisiz kişilerce haksız veya hukuka aykırı olarak kullanılması nedeni ile ilgili banka veya finans kuruluşun ürün bedelini SATICI’ya ödememesi halinde, ALICI’nın kendisine teslim edilmiş olması kaydıyla ürünün 3 gün içinde SATICI’ya gönderilmesi zorunludur. Bu takdirde nakliye giderleri ALICI’ya aittir. Eğer ALICI ürünü geri göndermezse kredi kartından herhangi bir nedenle ürün bedelinin alınmaması veya ürün bedelinin kredi kartına iade edilmesi durumlarında ürün bedelinin hiçbir ihtara gerek kalmaksızın SATICI banka hesaplarına havale edileceğini kabul ve taahhüt eder.\n\n4.10 SATICI mücbir sebepler veya nakliyeyi engelleyen hava muhalefeti, ulaşımın kesilmesi gibi olağanüstü durumlar nedeni ile sözleşme konusu ürünü süresi içinde teslim edemez ise, durumu ALICI’ya bildirmekle yükümlüdür. Bu takdirde ALICI siparişin iptal edilmesini, sözleşme konusu ürünün varsa emsali ile değiştirilmesini, ve/veya teslimat süresinin engelleyici durumun ortadan kalkmasına kadar ertelenmesi haklarından birini kullanabilir. ALICI’nın siparişi iptal etmesi halinde ödediği tutar 10 gün içinde kendisine nakden ve defaten ödenir.\n\n4.11 SATICI tarafından bir kampanya aracılığı ile müşteriye verilen puanlar sadece bir alışveriş için geçerlidir. Bu puanlar ürün iade edilse bile geri iade edilmez.\n\nALICI’nın kredi kartı ile yaptığı ödemelerde ise, ürün tutarı, siparişin ALICI tarafından iptal edilmesinden sonra 7 gün içerisinde ilgili bankaya iade edilir. Bu tutarın bankaya iadesinden sonra ALICI hesaplarına yansıması tamamen banka işlem süreci ile ilgili olduğundan, ALICI, olası gecikmeler için SATICI’nın herhangi bir şekilde müdahalede bulunmasının mümkün olamayacağını ve SATICI tarafından kredi kartına iade edilen tutarın banka tarafından ALICI hesabına yansıtılmasının ortalama 2 ile 3 haftayı bulabileceğini şimdiden kabul etmektedir.\n\nMADDE 5 – CAYMA HAKKI\n\nALICI, sözleşme konusu ürünün kendisine veya gösterdiği adresteki kişi/kuruluşa tesliminden itibaren 14 gün içinde hiçbir sebep göstermek zorunda olmaksızın cayma hakkına sahiptir.\n\nAncak, yılbaşı, bayramlar, anneler günü gibi belirli günlere yönelik ALICI’ya özel olarak hazırlanan, satışa sunulan ve/veya ithal edilen ürünlerde, kampanya ve promosyon ürünlerinde ürünün iadesi alınamamakta; ALICI bu şartları kabul ederek alışverişini gerçekleştirmektedir.\n\nCayma hakkının kullanılması için 14 günlük süre içinde SATICI’ya faks veya eposta ile bildirimde bulunulması ve ürünün 6. madde hükümleri çerçevesinde kullanılmamış olması şarttır. Bu hakkın kullanılması halinde,\n\na) 3. kişiye veya ALICI’ya teslim edilen ürünün faturası, (İade edilmek istenen ürünün faturası kurumsal ise, iade ederken kurumun düzenlemiş olduğu iade faturası ile birlikte gönderilmesi gerekmektedir. Faturası kurumlar adına düzenlenen sipariş iadeleri İADE FATURASI kesilmediği takdirde tamamlanamayacaktır)\n\nb) İade formu,\n\nc) 14 günlük süre içerisinde iade edilecek ürünlerin kutusu, ambalajı, varsa standart aksesuarları ile birlikte eksiksiz ve hasarsız olarak teslim edilmesi gerekmektedir. Bu belgelerin SATICI’ya ulaşmasını takip eden 10 gün içinde ürün bedeli ALICI’ya iade edilir.\n\nCayma hakkı nedeniyle iade edilen ürünün kargo bedeli yurtiçi siparişlerinde SATICI tarafından yurtdışı siparişlerinde ALICI tarafından karşılanacaktır. SATICI ürün satarken ALICI'dan tahsil ettiği kargo ücretini iade etmez.\n\nÜrün SATICI’ya iade edilirken, ürünün teslimi sırasında ALICI’ya ibraz edilmiş olan orijinal faturanın da (muhasebe kayıtlarımızda tutarlılığı sağlamak amacıyla) iade edilmesi gerekmekte olup faturanın ürünle birlikte ya da en geç ürünün gönderilmesinden itibaren 5 gün içerisinde SATICI’ya gönderilmemesi durumunda iade işlemi gerçekleştirilmeyecek, ürün aynı şekilde karşı ödemeli olarak ALICI’ya geri gönderilecektir. Ürünle beraber iade edilecek olan faturanın üzerine de “iade faturasıdır” ibaresi yazılıp ALICI tarafından imzalanacaktır.\n\nMADDE 6 – CAYMA HAKKI KULLANILAMAYACAK ÜRÜNLER\n\nALICI’nın isteği veya açıkça kişisel ihtiyaçları doğrultusunda hazırlanan ve geri gönderilmeye müsait olmayan, iç giyim alt parçaları, mayo ve bikini altları, makyaj malzemeleri, tek kullanımlık ürünler, çabuk bozulma tehlikesi olan veya son kullanma tarihi geçme ihtimali olan mallar, ALICI’ya teslim edilmesinin ardından ALICI tarafından ambalajı açıldığı takdirde iade edilmesi sağlık ve hijyen açısından uygun olmayan ürünler, teslim edildikten sonra başka ürünlerle karışan vedoğası gereği ayrıştırılması mümkün olmayan ürünler, Abonelik sözleşmesi kapsamında sağlananlar dışında, gazete ve dergi gibi süreli yayınlara ilişkin mallar, Elektronik ortamda anında ifa edilen hizmetler veya tüketiciye anında teslim edilen gayrimaddi mallar,ile ses veya görüntü kayıtlarının, kitap, dijital içerik, yazılım programlarının, veri kaydedebilme ve veri depolama cihazlarının, bilgisayar sarf malzemelerinin, ambalajının ALICI tarafından açılmış olması halinde iadesi Yönetmelik gereği mümkün değildir. Ayrıca Cayma hakkı süresi sona ermeden önce, tüketicinin onayı ile ifasına başlanan hizmetlere ilişkin cayma hakkının kullanılması daYönetmelik gereği mümkün değildir.\n\nKozmetik ve kişisel bakım ürünleri, iç giyim ürünleri, mayo, bikini, kitap, kopyalanabilir yazılım ve programlar, DVD, VCD, CD ve kasetler ile kırtasiye sarf malzemeleri (toner, kartuş, şerit vb.) iade edilebilmesi için ambalajlarının açılmamış, denenmemiş, bozulmamış ve kullanılmamış olmaları gerekir.\n\nMADDE 7 – BORÇLUNUN TEMERRÜDÜ\n\nALICI’nın temerrüde düşmesi halinde, ALICI, borcun gecikmeli ifasından dolayı SATICI’nın oluşan zarar ve ziyanını ödemeyi kabul eder. ALICI’nın temerrüdünün SATICI’nın kusurundan kaynaklandığı hallerde ALICI herhangi bir zarar ve ziyan talebini karşılamak mecburiyetinde olmayacaktır.\n\nMADDE 8 – YETKİLİ MAHKEME\n\nİş bu Ön Bilgilendirmenin uygulanmasında, Sanayi ve Ticaret Bakanlığınca ilan edilen değere kadar ALICI’nın mal veya hizmeti satın aldığı ve ikametgahının bulunduğu yerdeki Tüketici Hakem Heyetleri ile Tüketici Mahkemeleri yetkilidir.\n\nSATICI şikayet ve itirazları konusunda başvurularını, T.C. Sanayi Ve Ticaret Bakanlığı tarafından her yıl Aralık ayında belirlenen parasal sınırlar dâhilinde mal veya hizmeti satın aldığı veya ikametgahının bulunduğu yerdeki tüketici sorunları hakem heyetine veya tüketici mahkemesine yapabilir. Parasal sınıra ilişkin bilgiler aşağıdadır:\n\n28/05/2014 tarihinden itibaren geçerli olmak üzere;\n\na) 6502 sayılı Tüketicinin Korunması Hakkında Kanun'nun 68 inci maddesi gereği Değeri iki bin Türk Lirasının altında bulunan uyuşmazlıklarda ilçe tüketici hakem heyetlerine, üç bin Türk Lirasının altında bulunan uyuşmazlıklarda il tüketici hakem heyetlerine, büyükşehir statüsünde bulunan illerde ise iki bin Türk Lirası ile üç bin Türk Lirası arasındaki uyuşmazlıklarda il tüketici hakem heyetlerine başvuru zorunludur.Bu değerlerin üzerindeki uyuşmazlıklar için tüketici hakem heyetlerine başvuru yapılamaz.\n\nb) Belirtilen değer üzerinde olan uyuşmazlıklarda Tüketici Mahkemesinde, Tüketici Mahkemesinin bulunmadığı yerlerde ise Tüketici Mahkemesi sıfatıyla Asliye Hukuk Mahkemelerine başvurunun yapılması gerekmektedir.\n\nİş bu ön bilgilendirme ticari amaçla yapılmaktadır.\n\nLütfen Dikkat: Kargo tutanağını imzalamadan önce kargo paketinizin taşımadan dolayı hasarlı olup olmadığını lütfen kontrol ediniz. Kargo paketinizde herhangi bir nedenle hasar var ise teslimatla ilgili hiç bir belgeyi imzalamadan kargo yetkilisine tutanak tutulması için kargonuzu iade ediniz. Size tarafımızdan yeni ürünleriniz derhal gönderilecektir. Kargo paketi hasarlı olan ürünlerin teslim alınması durumunda içindeki ürünlerin hasarından veya eksikliğinden {store_domain} sorumlu değildir.\n\nBu şart ve koşulların tamamı Türk Hukukuna tabidir.",translations:{"en-US": {"title": "Distance Sales Agreement", "slug": "distance-sales-agreement", "body": "DISTANCE SALES AGREEMENT\n\nSELLER\nTrade name: {store_owner}\nAddress: {store_address}\nPhone: {store_telephone}\nEmail: {store_email}\n\nBUYER\nThe customer placing an order through {store_domain}; the identity, address and contact information supplied during the order is used.\n\nSUBJECT\nThis agreement governs the sale and delivery of products/services ordered electronically from {store_domain}, in accordance with Turkish consumer legislation, including Law No. 6502 and applicable distance-contract rules. Product type, quantity, price, payment and delivery details are those confirmed at checkout.\n\nThe SELLER is responsible for supplying the goods in conformity with the order. Delivery, payment, cancellation, refunds, force majeure and the statutory right of withdrawal are governed by applicable law and the pre-contract information presented to the BUYER. Statutory exceptions to the right of withdrawal apply where relevant. Mandatory consumer dispute-resolution and jurisdiction rules are reserved."}, "de-DE": {"title": "Fernabsatzvertrag", "slug": "mesafeli-satis-sozlesmesi-de", "body": "FERNABSATZVERTRAG\n\nVERKÄUFER: {store_owner}\nAdresse: {store_address}\nTelefon: {store_telephone}\nE-Mail: {store_email}\n\nKÄUFER ist die Person, die über {store_domain} bestellt. Gegenstand sind Verkauf und Lieferung der beim Checkout bestätigten Waren/Dienstleistungen nach türkischem Verbraucherrecht, insbesondere Gesetz Nr. 6502 und den Fernabsatzvorschriften. Produkteigenschaften, Preis, Zahlung, Lieferung, Rücktritt, Erstattung und gesetzliche Ausnahmen richten sich nach den beim Kauf angezeigten Informationen und den zwingenden Vorschriften."}, "ru-RU": {"title": "Договор дистанционной продажи", "slug": "mesafeli-satis-sozlesmesi-ru", "body": "ДОГОВОР ДИСТАНЦИОННОЙ ПРОДАЖИ\n\nПРОДАВЕЦ: {store_owner}\nАдрес: {store_address}\nТелефон: {store_telephone}\nE-mail: {store_email}\n\nПОКУПАТЕЛЬ — лицо, оформляющее заказ на {store_domain}. Договор регулирует продажу и доставку товаров/услуг, подтверждённых при оформлении заказа, в соответствии с турецким законодательством о защите потребителей, включая Закон № 6502. Характеристики, цена, оплата, доставка, отказ, возврат денежных средств и исключения определяются информацией при оформлении и обязательными нормами закона."}, "ar-SA": {"title": "اتفاقية البيع عن بُعد", "slug": "mesafeli-satis-sozlesmesi-ar", "body": "اتفاقية البيع عن بُعد\n\nالبائع: {store_owner}\nالعنوان: {store_address}\nالهاتف: {store_telephone}\nالبريد الإلكتروني: {store_email}\n\nالمشتري هو الشخص الذي يطلب من {store_domain}. تنظم هذه الاتفاقية بيع وتسليم السلع/الخدمات المؤكدة عند إتمام الطلب وفقاً لقانون حماية المستهلك التركي، بما في ذلك القانون رقم 6502 وقواعد العقود عن بُعد. تحدد تفاصيل المنتج والسعر والدفع والتسليم والعدول والاسترداد والاستثناءات وفق المعلومات المعروضة عند الشراء والقواعد القانونية الإلزامية."}}},
  {type:"MEMBERSHIP",slug:"uyelik-sozlesmesi",title:"Üyelik Sözleşmesi",body:"1. Taraflar\n\nİşbu Üyelik Sözleşmesi, {store_domain} internet sitesinin sahibi {store_address} adresinde mukim {store_owner} (bundan böyle “{store_name}” olarak anılacaktır) ile {store_domain} internet sitesine üye olan kullanıcı (“ÜYE”) arasında üyelik kaydı tarihinde akdedilir.\n\n2. Sözleşmenin Konusu\n\nİşbu Sözleşme'nin konusu, ÜYE'nin {store_domain} internet sitesinden yararlanma ve kullanma şartlarının belirlenmesidir.\n\n3. Tarafların Hak ve Yükümlülükleri\n\nÜYE, {store_domain} internet sitesini kullanırken yürürlükteki mevzuata uymayı kabul eder. ÜYE; hizmetleri engelleyici spam, virüs, zararlı yazılım ve benzeri faaliyetlerde bulunamaz; siteyi kamu düzenine, genel ahlaka, üçüncü kişilerin haklarına veya fikri mülkiyet haklarına aykırı amaçlarla kullanamaz.\n\nÜYE tarafından paylaşılan görüş ve yorumlardan, mevzuatın öngördüğü sınırlar içinde ÜYE sorumludur. ÜYE, üyelik sırasında verdiği bilgilerin doğru ve güncel olduğunu beyan eder.\n\nÜYE'nin şifre ve hesap bilgilerinin gizliliğini koruması gerekir. Yetkisiz kullanım şüphesi halinde {store_name} ile iletişim kurulmalıdır.\n\n{store_name}, üyelik ve mağaza hizmetlerinin güvenli ve düzenli çalışması için gerekli teknik ve idari tedbirleri alır. Siteye erişim sırasında IP adresi, erişim tarihi ve saati, ziyaret edilen sayfalar ve benzeri teknik kayıtlar güvenlik, hizmet kalitesi ve mevzuattan doğan yükümlülükler kapsamında işlenebilir.\n\nPazarlama ve ticari elektronik ileti faaliyetleri, ilgili mevzuat ve kullanıcının tercih/izinleri çerçevesinde yürütülür. Kullanıcı ileti tercihlerini mevzuatın öngördüğü yöntemlerle değiştirebilir.\n\n{store_name}, hizmetin içeriğini ve tasarımını geliştirebilir veya değiştirebilir. Sözleşme hükümleri mevzuata uygun olarak güncellenebilir ve güncel metin yayınlandığı tarihten itibaren uygulanır.\n\n4. Sözleşmenin Feshi\n\nTaraflar, mevzuat ve işbu sözleşme hükümleri çerçevesinde üyeliği sona erdirebilir. ÜYE'nin sözleşmeye veya hukuka aykırı davranması halinde üyelik askıya alınabilir veya sonlandırılabilir.\n\n5. Uyuşmazlıkların Çözümü\n\nTüketicinin yerleşim yeri ve tüketici mevzuatındaki emredici yetki kuralları saklıdır. Uyuşmazlıklarda yürürlükteki Türkiye Cumhuriyeti mevzuatı uygulanır.\n\n6. Yürürlük\n\nÜYE'nin üyelik kaydını tamamlayarak işbu sözleşmeyi kabul etmesiyle sözleşme yürürlüğe girer.",translations:{"en-US": {"title": "Membership Agreement", "slug": "membership-agreement", "body": "MEMBERSHIP AGREEMENT\n\nThis agreement is entered into between {store_owner}, operator of {store_domain}, and the user who registers as a member. It defines the conditions for using membership functions.\n\nMembers must provide accurate information, protect account credentials, comply with law and must not disrupt the service, upload malicious code or infringe third-party rights. Personal data is processed in accordance with the privacy/KVKK notices and commercial communications are sent only in accordance with applicable consent and legal requirements.\n\n{store_name} may update the service and these terms in accordance with law. Membership may be terminated by the user or suspended/terminated for material breach. Mandatory consumer rights and jurisdiction rules remain unaffected."}, "de-DE": {"title": "Mitgliedschaftsvereinbarung", "slug": "uyelik-sozlesmesi-de", "body": "MITGLIEDSCHAFTSVEREINBARUNG\n\nDiese Vereinbarung gilt zwischen {store_owner}, Betreiber von {store_domain}, und dem registrierten Mitglied. Mitglieder müssen richtige Angaben machen, Zugangsdaten schützen, Gesetze beachten und dürfen den Dienst nicht stören oder Rechte Dritter verletzen. Personenbezogene Daten werden nach den Datenschutz-/KVKK-Hinweisen verarbeitet. {store_name} kann den Dienst und die Bedingungen im Rahmen des geltenden Rechts aktualisieren. Zwingende Verbraucherrechte bleiben unberührt."}, "ru-RU": {"title": "Пользовательское соглашение", "slug": "uyelik-sozlesmesi-ru", "body": "ПОЛЬЗОВАТЕЛЬСКОЕ СОГЛАШЕНИЕ\n\nСоглашение заключается между {store_owner}, оператором {store_domain}, и зарегистрированным пользователем. Пользователь обязан предоставлять достоверные сведения, защищать данные доступа, соблюдать закон и не нарушать работу сервиса или права третьих лиц. Персональные данные обрабатываются согласно уведомлениям о конфиденциальности/KVKK. {store_name} может обновлять сервис и условия в рамках закона. Обязательные права потребителей сохраняются."}, "ar-SA": {"title": "اتفاقية العضوية", "slug": "uyelik-sozlesmesi-ar", "body": "اتفاقية العضوية\n\nتُبرم هذه الاتفاقية بين {store_owner}، مشغل {store_domain}، والمستخدم المسجل. يجب على العضو تقديم معلومات صحيحة وحماية بيانات الدخول والالتزام بالقانون وعدم تعطيل الخدمة أو انتهاك حقوق الغير. تتم معالجة البيانات الشخصية وفق إشعارات الخصوصية وKVKK. يجوز لـ {store_name} تحديث الخدمة والشروط وفق القانون. لا تتأثر حقوق المستهلك الإلزامية."}}},
] as const;
const contractMap:any={COOKIE_POLICY:'COOKIE_POLICY',PRIVACY:'PRIVACY',RETURNS:'RETURNS',TERMS:'TERMS',KVKK_NOTICE:'KVKK_NOTICE',DISTANCE_SALES:'DISTANCE_SALES'};
async function main(){
 const stores=await prisma.tenant.findMany({where:{status:{in:['TRIAL','ACTIVE']}}});
 for(const store of stores){const settings:any=store.settings||{};const mappings:any={...(settings.contractPages||{})};
  for(const d of docs){let page=await prisma.page.findUnique({where:{storeId_slug:{storeId:store.id,slug:d.slug}}});if(!page)page=await prisma.page.create({data:{storeId:store.id,title:d.title,slug:d.slug,body:d.body,status:'PUBLISHED',seoTitle:d.title,seoDescription:null}});else if(page.status!=='PUBLISHED')page=await prisma.page.update({where:{id:page.id},data:{status:'PUBLISHED'}});
   for(const [locale,t] of Object.entries(d.translations as any)){await prisma.contentTranslation.upsert({where:{storeId_entityType_entityId_locale:{storeId:store.id,entityType:'page',entityId:page.id,locale}},create:{storeId:store.id,entityType:'page',entityId:page.id,locale,fields:t as any},update:{}})}
   const mapKey=(contractMap as any)[d.type];if(mapKey&&!mappings[mapKey])mappings[mapKey]=page.id;
  }
  await prisma.tenant.update({where:{id:store.id},data:{settings:{...settings,contractPages:mappings,legalDefaultsVersion:'2026-09-21-v1'}}});
 }
 console.log(`[legal-pages-init] ${stores.length} active/trial store(s) checked; default legal pages published and contract mappings backfilled.`);
}
main().finally(()=>prisma.$disconnect());